<?php require '../config.php';require_admin();$message='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);if($action==='toggle'&&$id){$stmt=db()->prepare('UPDATE products SET is_active=1-is_active WHERE id=?');$stmt->bind_param('i',$id);$stmt->execute();$message='Product status updated.';}if($action==='create'){ $title=trim($_POST['title']??'');$description=trim($_POST['description']??'');$price=(float)($_POST['price']??0);$slug=preg_replace('/[^a-z0-9]+/','-',strtolower($title));if($title&&$description&&$price>=0){$file='storage/'.uniqid('asset_',true).'.pdf';$stmt=db()->prepare('INSERT INTO products(title,slug,description,price,file_path) VALUES(?,?,?,?,?)');$stmt->bind_param('sssds',$title,$slug,$description,$price,$file);$stmt->execute();$message='Product created.';}}}$products=db()->query('SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id ORDER BY p.created_at DESC');page_start('Manage products'); ?><section class="section-space"><div class="container"><div class="d-flex justify-content-between align-items-end mb-4"><div><div class="eyebrow">Catalog</div><h1 class="display-5 mb-0">Products.</h1></div><a href="index.php" class="text-dark fw-bold">← Dashboard</a></div><?php if($message): ?><div class="alert alert-success"><?= e($message) ?></div><?php endif; ?><div class="row g-4"><div class="col-lg-8"><div class="bg-white rounded-3 p-3 table-responsive"><table class="table align-middle"><thead><tr><th>Product</th><th>Price</th><th>Sales</th><th>Status</th><th></th></tr></thead><tbody><?php while($product=$products->fetch_assoc()): ?><tr><td><strong><?= e($product['title']) ?></strong><br><small class="text-muted"><?= e($product['category_name']??'Uncategorized') ?></small></td><td><?= money((float)$product['price']) ?></td><td><?= $product['sales_count'] ?></td><td><?= $product['is_active']?'Active':'Inactive' ?></td><td><form method="post"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?= $product['id'] ?>"><button class="btn btn-sm btn-outline-dark">Toggle</button></form></td></tr><?php endwhile; ?></tbody></table></div></div><div class="col-lg-4"><form method="post" class="bg-white rounded-3 p-4"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><input type="hidden" name="action" value="create"><h2 class="h5 mb-4">Quick add product</h2><div class="form-outline mb-3"><input class="form-control" name="title" required><label class="form-label">Title</label></div><div class="form-outline mb-3"><textarea class="form-control" name="description" rows="4" required></textarea><label class="form-label">Description</label></div><div class="form-outline mb-4"><input class="form-control" name="price" type="number" step="0.01" min="0" required><label class="form-label">Price</label></div><button class="btn btn-dark btn-rounded w-100">Create product</button></form></div></div></div></section><?php page_end(); ?>